Method.Implementation:
Set tSC= $$$OK $$$TRACE(" Inside InvokePostService ")
try { set httpBodyData = pInput.Read(.len,.status) $$$TRACE(" httpBody : "_httpBodyData)
set httpBodyParamsList = $LISTFROMSTRING(httpBodyData, "&") // name_first=MERGE1&name_middle=&name_last=XTEST&delete_mrn=789109&delete_mrn=123456 $$$TRACE("httpBodyParamsList::"_$LIST(httpBodyParamsList,1)) $$$TRACE("httpBodyParamsList::"_$LIST(httpBodyParamsList,2)) $$$TRACE("httpBodyParamsList::"_$LIST(httpBodyParamsList,3)) $$$TRACE("httpBodyParamsList::"_$LIST(httpBodyParamsList,4)) $$$TRACE("httpBodyParamsList::"_$LIST(httpBodyParamsList,5))
set firstNameList = $LISTFROMSTRING($LIST(httpBodyParamsList,1),"=") set midNameList = $LISTFROMSTRING($LIST(httpBodyParamsList,2),"=") set lastNameList = $LISTFROMSTRING($LIST(httpBodyParamsList,3),"=") set keepMrnList = $LISTFROMSTRING($LIST(httpBodyParamsList,4),"=") set deleteMrnList = $LISTFROMSTRING($LIST(httpBodyParamsList,5),"=")
Set firstName="" if ($LIST(firstNameList,1)="name_first"){ Set firstName=$LIST(firstNameList,2) $$$TRACE("First Name : "_firstName) }
Set midName="" if ($LIST(midNameList,1)="name_middle"){ Set midName=$LIST(midNameList,2) $$$TRACE("Mid Name : "_midName) }
Set lastName="" if ($LIST(lastNameList,1)="name_last"){ Set lastName=$LIST(lastNameList,2) $$$TRACE("Last Name : "_lastName) }
Set keepMrn="" if ($LIST(keepMrnList,1)="keep_mrn"){ Set keepMrn=$LIST(keepMrnList,2) $$$TRACE("Keep Mrn : "_keepMrn) }
Set deleteMrn="" if ($LIST(deleteMrnList,1)="delete_mrn"){ Set deleteMrn=$LIST(deleteMrnList,2) $$$TRACE("Delete Mrn : "_deleteMrn) }
Set pResponse=##class(IHC.ITF.Response.mPageMergeDataResponse).%New() Set pResponse.delMrn = deleteMrn Set pResponse.keepMrn = keepMrn Set pResponse.lastName = lastName Set pResponse.firstName = firstName Set pResponse.midName = midName
do ..SendRequestAsync(..TargetConfigNames,pResponse)
}catch e { $$$TRACE(" Unknown Exception: " _ e) set errTxt = $System.Status.GetErrorText("Unknown Exception while receiving post request from mPage. "_e) Set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError(..%ConfigName,errTxt) set tSC = $$$OK
} quit tSC
